def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Every aligned pair of markers draws a segment between its endpoints.
    lines = set()
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 1]
        for i, a in enumerate(cols):
            for b in cols[i+1:]:
                lines.update((r, c) for c in range(a, b+1))
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 1]
        for i, a in enumerate(rows):
            for b in rows[i+1:]:
                lines.update((r, c) for r in range(a, b+1))
    # Recolor each 4-connected 2-shape struck by one of those lines.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            comp, stack = {(r, c)}, [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
            if comp & lines:
                for rr, cc in comp:
                    out[rr][cc] = 1
    for r, c in lines:
        out[r][c] = 1
    return out

